#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/structures_extended.hpp>
#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions (DATA_TYPE, NR, NQ, NP, ...)
#include "defines.hpp"

// include benchmark-specific definitions (NR, NQ, NP, etc.)
#include "doitgen.hpp"

using num_t = DATA_TYPE;

namespace {

// ---------------------------------------------------------------------------
// Dimension and layout definitions
// ---------------------------------------------------------------------------

// dimension prototypes
constexpr auto r_vec = noarr::vector<'r'>(); // corresponds to C index r (0..NR-1)
constexpr auto q_vec = noarr::vector<'q'>(); // corresponds to C index q (0..NQ-1)
constexpr auto p_vec = noarr::vector<'p'>(); // corresponds to C index p (0..NP-1)
constexpr auto s_vec = noarr::vector<'s'>(); // corresponds to C index s (0..NP-1)

// layouts (match C memory layout: last index varies fastest)
// A[r][q][p]
constexpr auto A_layout  = p_vec ^ q_vec ^ r_vec;
// C4[s][p]
constexpr auto C4_layout = p_vec ^ s_vec;
// sum[p]
constexpr auto sum_layout = p_vec;

// ---------------------------------------------------------------------------
// Initialization
// ---------------------------------------------------------------------------

void init_array(auto A, auto C4) {
	using namespace noarr;

	// Length in 'p' is constant for whole run; compute once instead of per element.
	const auto np_len_A  = A  | get_length<'p'>();
	const auto np_len_C4 = C4 | get_length<'p'>();

	// A[r][q][p] = ((r*q + p) % np) / np;
	traverser(A).for_each([=](auto state) {
		auto [r, q, p] = get_indices<'r', 'q', 'p'>(state);

		A[state] = static_cast<num_t>(( (r * q + p) % np_len_A ))
			/ static_cast<num_t>(np_len_A);
	});

	// C4[s][p] = (s*p % np) / np;
	traverser(C4).for_each([=](auto state) {
		auto [s, p] = get_indices<'s', 'p'>(state);

		C4[state] = static_cast<num_t>(( (s * p) % np_len_C4 ))
			/ static_cast<num_t>(np_len_C4);
	});
}

// ---------------------------------------------------------------------------
// Computation kernel
// ---------------------------------------------------------------------------
//
// Original C kernel (PolyBench doitgen):
//
// for (r)
//   for (q) {
//     for (p) {
//       sum[p] = 0;
//       for (s)
//         sum[p] += A[r][q][s] * C4[s][p];
//     }
//     for (p)
//       A[r][q][p] = sum[p];
//   }
//
// This computes, for each (r,q), a matrix–vector product:
//
//   sum[p] = Σ_s A[r][q][s] * C4[s][p]
//
// The naive loop order is r, q, p, s. That has very poor locality for C4
// (accesses a column C4[*][p] with large strides) and repeatedly reloads
// A[r][q][s] for every p.
//
// The optimized kernel below keeps the **same mathematical result**, but
// changes the reduction order for each (r,q) to:
//
//   for p: sum[p] = 0
//   for s:
//     a = A[r][q][s]
//     for p:
//       sum[p] += a * C4[s][p]
//   for p:
//     A[r][q][p] = sum[p]
//
// i.e. loop order r, q, s, p. This:
//
//   - reads A[r][q][s] once per (r,q,s) and reuses it over all p
//   - walks C4[s][p] with p inner-most (row-major, contiguous in memory)
//   - keeps sum[p] contiguous and streaming in p
//
// All loops are expressed using Noarr traversers as required.
//
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	// Compile-time toggle to switch between the optimized (r,q,s,p) ordering
	// and a fallback variant close to the original (r,q,p,s) ordering.
	// This can be used to experiment with different loop orders on specific
	// hardware without touching the algorithmic code.
	constexpr bool use_reordered_loops = true;

#pragma scop
	if constexpr (use_reordered_loops) {
		// Optimized variant: r, q, s, p

		// Traverser for C4 reused for every (r,q) pair
		auto trav_C4 = traverser(C4);

		// Outer loops over r and q; A and sum share 'p', but sum ignores 'r' and 'q'
		traverser(A, sum).template for_dims<'r', 'q'>([&](auto trav_rq) {
			// Fixed (r,q) for this inner traverser
			auto rq_state = trav_rq.state();
			auto [r_idx, q_idx] = get_indices<'r', 'q'>(rq_state);

			// ------------------------------------------------------------------
			// 1) Initialize sum[p] = 0 for all p at this (r,q)
			//    We use trav_rq.for_dims<'p'> so that the traversal length in 'p'
			//    is taken from A/sum automatically.
			// ------------------------------------------------------------------
			trav_rq.template for_dims<'p'>([&](auto trav_rqp) {
				auto state_rqp = trav_rqp.state(); // contains r, q, p
				// sum uses only 'p'; extra indices ('r','q') are ignored
				sum[state_rqp] = static_cast<num_t>(0);
			});

			// ------------------------------------------------------------------
			// 2) Reduction over s and p:
			//
			//    for (s)
			//      a_rqs = A[r][q][s];
			//      for (p)
			//        sum[p] += a_rqs * C4[s][p];
			//
			//    We iterate C4 with s outer, p inner to get contiguous access
			//    in C4's 'p' dimension.
			// ------------------------------------------------------------------
			trav_C4.template for_dims<'s'>([&](auto trav_s) {
				auto s_state = trav_s.state();
				auto s_idx = get_index<'s'>(s_state);

				// A[r][q][s] – 'p' is the last dimension of A and corresponds to s here
				const num_t a_rqs =
					A[noarr::idx<'r', 'q', 'p'>(r_idx, q_idx, s_idx)];

				// For fixed s, sweep all p contiguously in C4[s][p]
				trav_s.template for_dims<'p'>([&](auto trav_sp) {
					auto sp_state = trav_sp.state(); // contains s, p

					// C4[s][p] – both dimensions are present in sp_state
					const num_t c4_val = C4[sp_state];

					// sum[p] – sum has only 'p'; extra 's' in the state is ignored
					sum[sp_state] += a_rqs * c4_val;
				});
			});

			// ------------------------------------------------------------------
			// 3) Copy the accumulated sums back into A:
			//      A[r][q][p] = sum[p]  for all p
			// ------------------------------------------------------------------
			trav_rq.template for_dims<'p'>([&](auto trav_rqp) {
				auto state_rqp = trav_rqp.state(); // contains r, q, p

				// sum[p] – uses only 'p', ignores 'r' and 'q' in state_rqp
				A[state_rqp] = sum[state_rqp];
			});
		});
	} else {
		// Fallback: structurally close to the original r, q, p, s ordering.
		// Kept as a reference / tuning knob. Not normally used when
		// use_reordered_loops == true.

		traverser(A, sum).template for_dims<'r', 'q'>([=](auto trav_rq) {

			// First loop over p: compute sum[p] = Σ_s A[r][q][s] * C4[s][p]
			trav_rq.template for_dims<'p'>([=](auto trav_rqp) {
				auto state_rqp = trav_rqp.state(); // contains indices r, q, p

				// sum[p] = 0.0;
				sum[state_rqp] = static_cast<num_t>(0);

				// extract indices r, q, p
				auto r_idx = get_index<'r'>(state_rqp);
				auto q_idx = get_index<'q'>(state_rqp);
				auto p_idx = get_index<'p'>(state_rqp);

				// view of C4 with fixed column p_idx: C4[s][p_idx]
				auto C4_p = C4 ^ noarr::fix<'p'>(p_idx);

				// inner loop over s
				noarr::traverser(C4_p).for_each([=](auto state_s) {
					auto s_idx = get_index<'s'>(state_s);

					// A[r][q][s]
					auto state_rqs = noarr::idx<'r', 'q', 'p'>(r_idx, q_idx, s_idx);

					// sum[p] += A[r][q][s] * C4[s][p]
					sum[state_rqp] += A[state_rqs] * C4_p[state_s];
				});
			});

			// Second loop over p: A[r][q][p] = sum[p]
			trav_rq.template for_dims<'p'>([=](auto trav_rqp) {
				auto state_rqp = trav_rqp.state();
				A[state_rqp] = sum[state_rqp];
			});
		});
	}
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

	// allocate data (bags)
	auto A = noarr::make_bag(
		noarr::scalar<num_t>()
		^ A_layout
		^ noarr::set_length<'r'>(nr)
		^ noarr::set_length<'q'>(nq)
		^ noarr::set_length<'p'>(np));

	auto C4 = noarr::make_bag(
		noarr::scalar<num_t>()
		^ C4_layout
		^ noarr::set_length<'s'>(np)
		^ noarr::set_length<'p'>(np));

	auto sum = noarr::make_bag(
		noarr::scalar<num_t>()
		^ sum_layout
		^ noarr::set_length<'p'>(np));

	// initialize arrays
	init_array(A.get_ref(), C4.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_doitgen(A.get_ref(), C4.get_ref(), sum.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optionally print output (to prevent DCE and to check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'r' for a more natural outer dimension in the dump
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'r'>());
	}

	// print elapsed time in seconds
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
