// -----------------------------------------------------------------------------
// Computation kernel
// -----------------------------------------------------------------------------
//
// Original C kernel:
//
//   for (r)
//     for (q) {
//       for (p) {
//         sum[p] = 0;
//         for (s)
//           sum[p] += A[r][q][s] * C4[s][p];
//       }
//       for (p)
//         A[r][q][p] = sum[p];
//     }
//
// This computes, for each fixed (r, q), a matrix–vector-like product:
//
//   A_new[r,q,p] = Σ_s A_old[r,q,s] * C4[s,p]
//
// We legally reorder the inner loops to improve locality:
//
//   for (r)
//     for (q) {
//       for (p) sum[p] = 0;
//       for (s) {
//         a = A[r][q][s];
//         for (p) sum[p] += a * C4[s][p];
//       }
//       for (p) A[r][q][p] = sum[p];
//     }
