// The blocking factor is a single tunable compile-time constant.
// -----------------------------------------------------------------------------

// Tunable block size along the contiguous 'p' dimension in the (s,p) traversal.
// Adjusting this constant allows tuning for different cache hierarchies / SIMD
// widths without changing the algorithmic code.
constexpr std::size_t DOITGEN_BLOCK_P = 64;

[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	// Proto-structure describing blocked traversal along 'p'.
	// We use into_blocks_dynamic so we correctly handle cases where NP is not
	// an exact multiple of DOITGEN_BLOCK_P. This affects *only* the traversal
	// order; logical indices in the states remain just {'s','p'} thanks to
	// traverser(order(...)) semantics.
	const auto block_p_proto =
		noarr::into_blocks_dynamic<'p', 'P', 'p', 'b'>(DOITGEN_BLOCK_P);

#pragma scop
	// Outer traversal over r and q (rows of the 3D tensor A).
	// traverser(A, sum) ensures that indices for 'p' used with sum are
	// compatible with those used for A.
	traverser(A, sum).template for_dims<'r', 'q'>([&](auto trav_rq) {
		// trav_rq has 'r' and 'q' fixed, 'p' is still free in A.
		auto state_rq = trav_rq.state();
		auto r_idx = get_index<'r'>(state_rq);
		auto q_idx = get_index<'q'>(state_rq);

		// View of A for fixed (r,q): one-dimensional vector over 'p'.
		// A_rq[p] <-> A[r][q][p]
		auto A_rq = A ^ fix<'r'>(r_idx) ^ fix<'q'>(q_idx);

		// ---------------------------------------------------------------------
		// 1) Initialize temporary sum[p] for this (r,q)
		// ---------------------------------------------------------------------
		//
		// sum is a 1D bag over 'p'. Extra dimensions in state are ignored by
		// bag indexing, so we simply traverse sum by its own structure.
		traverser(sum).for_each([&](auto state_p) {
			sum[state_p] = static_cast<num_t>(0);
		});

		// ---------------------------------------------------------------------
		// 2) Accumulate: sum[p] += Σ_s A[r][q][s] * C4[s][p]
		// ---------------------------------------------------------------------
		//
		// We traverse C4 in a cache-friendly order:
		//   outer  : 's'
		//   middle : blocks of 'p' (dimension 'P')
		//   inner  : 'p' inside each block (contiguous in memory)
		//
		// Thanks to traverser(order(block_p_proto)), the states seen here
		// still only contain the original dimensions {'s','p'}; 'P' and 'b'
		// are internal to the traversal and do not affect indexing.
		traverser(C4)
			.order(block_p_proto)
			.template for_dims<'s'>([&](auto trav_s) {
				// trav_s has 's' fixed; remaining free dimensions are the
				// blocked representation of 'p'.
				auto s_state = trav_s.state();
				auto s_idx = get_index<'s'>(s_state);

				// Load A[r][q][s] once per (r, q, s).
				const num_t a_rqs = A_rq[noarr::idx<'p'>(s_idx)];

				// Iterate blocks of 'p' for this fixed 's'.
				trav_s.template for_dims<'P'>([&](auto trav_sP) {
					// Inside each block, for_each iterates the remaining
					// dimensions, which (from our point of view) is just 'p'.
					trav_sP.for_each([&](auto state_sp) {
						// state_sp carries {'s','p'} only.
						// Both C4 and sum use 'p'; 's' is ignored by sum.
						sum[state_sp] += a_rqs * C4[state_sp];
					});
				});
			});

		// ---------------------------------------------------------------------
		// 3) Write back: A[r][q][p] = sum[p]
		// ---------------------------------------------------------------------
		traverser(sum).for_each([&](auto state_p) {
			A_rq[state_p] = sum[state_p];
		});
	});
#pragma endscop
}

