	using namespace noarr;

#pragma scop
	// Outer loops over r and q: handled via for_dims<'r','q'>
	// The traverser is constructed over both A and sum, so states
	// carry indices (r,q,p) when needed and sum ignores extra dims.
	traverser(A, sum).template for_dims<'r', 'q'>([&](auto trav_rq) {

