		// state_rq contains exactly 'r' and 'q'.
		const auto state_rq = trav_rq.state();

		// ------------------------------------------------------------------
		// 1) Zero the whole sum-vector for this (r,q)
		//    This corresponds to:
		//      for (p) sum[p] = 0;
		// ------------------------------------------------------------------
		traverser(sum).for_each([&](auto state_p) {
			// state_p only has 'p'; any extra dims in the structure
			// (none here) would be ignored automatically.
			sum[state_p] = static_cast<num_t>(0);
		});

