		// 2) Accumulate contributions into sum[p]
		//
		//    We traverse C4 by rows: 's' is hoisted as the explicit
		//    outer dimension via for_dims<'s'>, and 'p' is iterated
		//    by for_each on the inner traverser.
		//
		//    This corresponds to:
		//      for (s) {
		//        a_val = A[r][q][s];
		//        for (p)
		//          sum[p] += a_val * C4[s][p];
		//      }
		//
		//    Note:
		//      - A[r][q][s] is accessed along the innermost 'p' dimension,
		//        so as s increases we stream through A[r][q][*] contiguously.
		//      - C4[s][p] is accessed contiguously along 'p' for each fixed s.
		// ------------------------------------------------------------------
		traverser(C4).template for_dims<'s'>([&](auto trav_s) {
			// trav_s has 's' fixed, 'p' remaining.
			const auto state_s = trav_s.state();
			const auto s_idx   = get_index<'s'>(state_s);

			// Compute A[r][q][s] once and reuse it across all p for this s.
			const auto state_rqs = state_rq + idx<'p'>(s_idx); // adds 'p' = s
			const num_t a_rqs = A[state_rqs];

			// Inner loop over p for this fixed s: contiguous over 'p' in C4.
			trav_s.for_each([&](auto state_sp) {
				// state_sp carries 's' and 'p'; sum only cares about 'p'.
				sum[state_sp] += a_rqs * C4[state_sp];
			});
		});

		// ------------------------------------------------------------------
		// 3) Write back the result vector sum[p] into A[r][q][p]
		//
		//    This corresponds to:
		//      for (p)
		//        A[r][q][p] = sum[p];
		//
		//    We reuse the (r,q) fixing via trav_rq and just iterate
	//    over the remaining 'p' dimension.
		// ------------------------------------------------------------------
		trav_rq.for_each([&](auto state_rqp) {
			// state_rqp has 'r','q','p'; sum ignores 'r' and 'q'.
			A[state_rqp] = sum[state_rqp];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t nr = NR;
	std::size_t nq = NQ;
	std::size_t np = NP;

