template<std::size_t P_BLOCK = 0>
[[gnu::flatten, gnu::noinline]]
void kernel_doitgen(auto A, auto C4, auto sum) {
	using namespace noarr;

	// We assume A and C4 are sized consistently so that:
	//   len_p_A == len_p_C4 == len_s_C4 == NP
	const std::size_t np_len = A | get_length<'p'>();

#pragma scop
	// Traverse the (r, q) pair explicitly; A and sum share the 'p' dimension.
	traverser(A, sum).template for_dims<'r', 'q'>([&](auto trav_rq) {
		const auto state_rq = trav_rq.state();
		const std::size_t r_idx = get_index<'r'>(state_rq);
		const std::size_t q_idx = get_index<'q'>(state_rq);

		// ------------------------------------------------------------------
		// 1) Initialize temporary sum[p] for this (r, q)
		// ------------------------------------------------------------------
		traverser(sum).for_each([&](auto state_p) {
			sum[state_p] = static_cast<num_t>(0);
		});

		// ------------------------------------------------------------------
		// 2) Main accumulation:
		//      sum[p] += A[r][q][s] * C4[s][p]
		//    with s outer and p inner to achieve:
		//      - contiguous accesses in C4 along p
		//      - contiguous updates of sum along p
		//      - A[r][q][s] loaded once per (r,q,s)
		// ------------------------------------------------------------------

		if constexpr (P_BLOCK == 0) {
			// No explicit blocking: straightforward s-then-p traversal.

			// Iterate over s using C4's 's' dimension.
			traverser(C4).template for_dims<'s'>([&](auto trav_s) {
				const auto state_s = trav_s.state();
				const std::size_t s_idx = get_index<'s'>(state_s);

				// A[r][q][s] -> use 'p' dimension as the s index
				const num_t a_rqs = A[noarr::idx<'r', 'q', 'p'>(r_idx, q_idx, s_idx)];

				// Fix one row of C4: C4_row_s[p] = C4[s_idx][p]
				auto C4_row_s = C4 ^ noarr::fix<'s'>(s_idx);

				// For all p: sum[p] += A[r][q][s] * C4[s][p]
				traverser(sum, C4_row_s).for_each([&](auto state_p) {
					sum[state_p] += a_rqs * C4_row_s[state_p];
				});
			});

