			// Blocked version along the p dimension.
			// P_BLOCK is a compile-time constant; this path can be enabled
			// by instantiating the template with P_BLOCK > 0.

			constexpr std::size_t block_size = P_BLOCK;

			traverser(C4).template for_dims<'s'>([&](auto trav_s) {
				const auto state_s = trav_s.state();
				const std::size_t s_idx = get_index<'s'>(state_s);

				const num_t a_rqs = A[noarr::idx<'r', 'q', 'p'>(r_idx, q_idx, s_idx)];

				// Fix one row of C4: C4_row_s[p] = C4[s_idx][p]
				auto C4_row_s = C4 ^ noarr::fix<'s'>(s_idx);

